assert all(all(len(h)==2 and all(h) for h in w['history']) for w in W)
for kind,data in [('roots',roots),('words',W)]: (OUT/f'{kind}_batch200_st_19.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
